"use client"

import animation from "react-useanimations/lib/phoneCall"

import { UseAnimation, type UseAnimationProps } from "@/components/use-animation"

// "Phone Call" from https://useanimations.com (MIT): https://useanimations.com/icons/phone-call
export function AnimatedPhoneCall(
  props: Omit<UseAnimationProps, "animationData">
) {
  return (
    <UseAnimation
      animationData={animation.animationData}
      interaction="click-replay"
      {...props}
    />
  )
}
